INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Rollen-und-Rechte-Konzept nur für große Teams nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams brauchen Klarheit"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Rollen-und-Rechte-Konzept?', 3, '[{"text": "Verantwortlichkeiten definieren", "correct": true, "because": "Klarheit über Zugriffsrechte"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Rollen-und-Rechte-Konzept?', 5, '[{"text": "Rollenzuweisung", "correct": true, "because": "Definiert Verantwortlichkeiten"}, {"text": "Zugriffsrechte", "correct": true, "because": "Legt Berechtigungen fest"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rollen reduzieren Sicherheitsrisiken. b) Jeder Mitarbeiter braucht volle Rechte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Begrenzte Rechte erhöhen Sicherheit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Rollen-und-Rechte-Konzept?', 4, '[{"text": "Rollenverteilung", "correct": false, "because": "Kern der Struktur"}, {"text": "Berechtigungsstufen", "correct": false, "because": "Definiert Zugriff"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Rollen-und-Rechte-Konzept auch physischen Zugang regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Kann Zutrittsrechte umfassen"}, {"text": "Nein", "correct": false, "because": "Nicht nur IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist typisch für ein Rollen-und-Rechte-Konzept?', 3, '[{"text": "Least Privilege", "correct": true, "because": "Minimale Rechte vergeben"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Irrelevant"}, {"text": "Statische IPs", "correct": false, "because": "Kein Rechtefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze gehören zu einem Rollen-und-Rechte-Konzept?', 5, '[{"text": "Rollenbasierte Zugriffskontrolle", "correct": true, "because": "Regelt Berechtigungen"}, {"text": "Rechteprüfung", "correct": true, "because": "Sichert Zugriff"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Rollen-und-Rechte-Konzepte erhöhen Sicherheit. b) Alle Mitarbeiter brauchen Admin-Rechte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Admin-Rechte nur bei Bedarf"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Rollen-und-Rechte-Konzept?', 4, '[{"text": "Rollenzuordnung", "correct": false, "because": "Kern der Definition"}, {"text": "Zugriffsbeschränkung", "correct": false, "because": "Schützt Daten"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Regelt ein Rollen-und-Rechte-Konzept nur IT-Zugriff?', 2, '[{"text": "Nein", "correct": true, "because": "Auch physische Rechte möglich"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien unterstützen ein Rollen-und-Rechte-Konzept?', 4, '[{"text": "Need-to-Know", "correct": true, "because": "Nur nötige Rechte"}, {"text": "Segregation of Duties", "correct": true, "because": "Aufgaben trennen"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Rollen-und-Rechte-Konzept optional ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Pflicht für Sicherheit"}, {"text": "Ja", "correct": false, "because": "Risikoreduktion nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Rollen-und-Rechte-Konzept?', 3, '[{"text": "Minimale Rechte", "correct": true, "because": "Sichert Least Privilege"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Grafische Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rollen definieren Zugriffsrechte. b) Alle Mitarbeiter brauchen gleiche Rechte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Individuelle Rechte nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zu einem Rollen-und-Rechte-Konzept?', 5, '[{"text": "RBAC", "correct": true, "because": "Rollenbasierte Zugriffskontrolle"}, {"text": "Rechteüberprüfung", "correct": true, "because": "Sichert Zugriff"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Rollen-und-Rechte-Konzept unwichtig?', 3, '[{"text": "Rollenverteilung", "correct": false, "because": "Kern der Sicherheit"}, {"text": "Rechtevergabe", "correct": false, "because": "Definiert Zugriff"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt ein Rollen-und-Rechte-Konzept vor Datenlecks?', 3, '[{"text": "Ja", "correct": true, "because": "Begrenzte Rechte reduzieren Risiken"}, {"text": "Nein", "correct": false, "because": "Effektiver Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Rollen-und-Rechte-Konzept regelmäßig überprüft werden sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassung an Änderungen"}, {"text": "Nein", "correct": false, "because": "Aktualisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für ein Rollen-und-Rechte-Konzept?', 4, '[{"text": "Least Privilege", "correct": true, "because": "Minimale Rechte vergeben"}, {"text": "Hohe Latenz", "correct": false, "because": "Irrelevant"}, {"text": "Großer Speicher", "correct": false, "because": "Kein Schutzfaktor"}]');
